    "ca_yuji": {//势于吉
        "经典形象": {
            "skill": {
                "cafuji1": "天地有常法，不失铢分也。",
                "cafuji2": "天者养人命，地者养人形。",
                "cafuji3": "此符上格神明，下通幽府，有诸般之神效。",
                "cafuji4": "得天意者寿，失天意者亡。",
                "cafuji5": "吾所书之符尚可鞭笞百鬼，更况些许小疾。",
                "cadaozhuan1": "哀哉！有志之士，早计早计，无负今言。",
                "cadaozhuan2": "吾承天道法，闭其凶恶之路，开天太平之阶。",
                "cadaozhuan3": "不学无求贤，不耕无求收，子知之乎？",
                "cadaozhuan4": "幸欲报天地之功而得寿者，努力信道勿懈。",
                "die": "子为愚者，尚迷不信道，堕卑贱苦，岂不哀哉",
                "victory": "夫寿命，天之重宝也，所以私有德，不可伪致。",
            }
        },
        "形全精复": {
            "order": "1",
            "skill": {
                "cafuji1": "病者跪拜首过，复饮符水则百病皆却也。",
                "cafuji2": "以言愈病，此天上神谶语也。",
                "cafuji3": "蠕动之属皆有知，勿轻杀伤用之也。",
                "cafuji4": "力行善反得恶者，是承负先人之过。",
                "cafuji5": "倘若信道诚心，此疾不日即愈。",
                "cadaozhuan1": "人可思念，皆有可致，在可思者优劣而已。",
                "cadaozhuan2": "习善言，不若习行于身也。",
                "cadaozhuan3": "用口多者竭其精，用力多者劳其形。",
                "cadaozhuan4": "黑文者死，青录者生，生死名簿，在天明堂。",
                "die": "吾一生修持，惟愿不失天意，得获天心。",
                "victory": "为人父母，当广积善行，为后生者计。",
            }
        }
    },
